import logging
from typing import Any, Dict, Optional
from fastmcp import Context
from kubectl_mcp_tool.safety import get_safety_mode, SafetyMode

logger = logging.getLogger("mcp-server")


async def check_write_allowed() -> Optional[Dict[str, Any]]:
    """Check if write operations are allowed in current safety mode.

    Use for non-destructive write tools (create, scale, update, restart).
    Only blocks in READ_ONLY mode. Returns None if allowed, error dict if blocked.
    """
    mode = get_safety_mode()
    if mode == SafetyMode.READ_ONLY:
        return {"success": False, "error": "Blocked: read-only mode"}
    return None


async def confirm_destructive(
    ctx: Context,
    operation: str,
    resource: str,
    namespace: str = "",
) -> Optional[Dict[str, Any]]:
    """Request user confirmation before destructive operations.

    Use for destructive tools (delete, uninstall, drop). Blocks in READ_ONLY
    and DISABLE_DESTRUCTIVE modes. Prompts for confirmation in CONFIRM mode.
    Returns None if approved, error dict if blocked/declined.
    """
    mode = get_safety_mode()

    if mode == SafetyMode.READ_ONLY:
        return {"success": False, "error": "Blocked: read-only mode"}
    if mode == SafetyMode.DISABLE_DESTRUCTIVE:
        return {"success": False, "error": "Blocked: destructive operations disabled"}
    if mode == SafetyMode.NORMAL:
        return None

    if mode == SafetyMode.CONFIRM:
        if ctx is None:
            return {"success": False, "error": "Blocked: no client context for confirmation prompt"}
        prompt = f"{operation} '{resource}'"
        if namespace:
            prompt += f" in namespace '{namespace}'"
        prompt += "?"
        try:
            result = await ctx.elicit(prompt)
            if result.action == "accept":
                return None
            return {"success": False, "error": "Operation cancelled by user"}
        except (NotImplementedError, AttributeError) as e:
            logger.debug(f"Elicitation not supported by client: {e}")
            return {"success": False, "error": "Blocked: client doesn't support confirmation prompts"}
        except Exception as e:
            logger.warning(f"Unexpected error during elicitation: {e}")
            return {"success": False, "error": "Blocked: client doesn't support confirmation prompts"}

    return None

import logging
import subprocess
from typing import Any, Dict, List, Optional

from mcp.types import ToolAnnotations

from ..k8s_config import (
    get_apps_client,
    get_batch_client,
    get_autoscaling_client,
    get_policy_client,
    _load_config_for_context,
    _get_kubectl_context_args,
)
from kubectl_mcp_tool.schemas import GetDeploymentsResponse
from kubectl_mcp_tool.structured import structured_response

logger = logging.getLogger("mcp-server")


def register_deployment_tools(server: "FastMCP", non_destructive: bool):
    """Register deployment and workload management tools."""
    from kubectl_mcp_tool.elicit import check_write_allowed

    @server.tool(
        output_schema=GetDeploymentsResponse.model_json_schema(),
        annotations=ToolAnnotations(
            title="Get Deployments",
            readOnlyHint=True,
            destructiveHint=False,
            idempotentHint=True,
            openWorldHint=True,
        ),
    )
    def get_deployments(
        namespace: Optional[str] = None,
        context: str = ""
    ) -> Dict[str, Any]:
        """Get all deployments in the specified namespace.

        Args:
            namespace: Namespace to list deployments from (all namespaces if not specified)
            context: Kubernetes context to use (uses current context if not specified)
        """
        try:
            apps = get_apps_client(context)

            if namespace:
                deployments = apps.list_namespaced_deployment(namespace)
            else:
                deployments = apps.list_deployment_for_all_namespaces()

            return structured_response({
                "success": True,
                "context": context or "current",
                "deployments": [
                    {
                        "name": d.metadata.name,
                        "namespace": d.metadata.namespace,
                        "replicas": d.spec.replicas,
                        "ready": d.status.ready_replicas or 0,
                        "available": d.status.available_replicas or 0
                    }
                    for d in deployments.items
                ]
            }, GetDeploymentsResponse)
        except Exception as e:
            logger.error(f"Error getting deployments: {e}")
            return {"success": False, "error": str(e)}

    @server.tool(
        annotations=ToolAnnotations(
            title="Create Deployment",
            readOnlyHint=False,
            destructiveHint=False,
            idempotentHint=False,
            openWorldHint=True,
        ),
    )
    async def create_deployment(
        name: str,
        image: str,
        replicas: int,
        namespace: Optional[str] = "default",
        context: str = "",
    ) -> Dict[str, Any]:
        """Create a new deployment.

        Args:
            name: Name of the deployment
            image: Container image to deploy
            replicas: Number of replicas
            namespace: Namespace to create deployment in (default: "default")
            context: Kubernetes context to use (uses current context if not specified)
        """
        blocked = await check_write_allowed()
        if blocked:
            return blocked
        try:
            from kubernetes import client

            apps = get_apps_client(context)

            deployment = client.V1Deployment(
                metadata=client.V1ObjectMeta(name=name),
                spec=client.V1DeploymentSpec(
                    replicas=replicas,
                    selector=client.V1LabelSelector(
                        match_labels={"app": name}
                    ),
                    template=client.V1PodTemplateSpec(
                        metadata=client.V1ObjectMeta(labels={"app": name}),
                        spec=client.V1PodSpec(
                            containers=[
                                client.V1Container(
                                    name=name,
                                    image=image
                                )
                            ]
                        )
                    )
                )
            )

            apps.create_namespaced_deployment(namespace, deployment)
            return {
                "success": True,
                "context": context or "current",
                "message": f"Deployment {name} created"
            }
        except Exception as e:
            logger.error(f"Error creating deployment: {e}")
            return {"success": False, "error": str(e)}

    @server.tool(
        annotations=ToolAnnotations(
            title="Scale Deployment",
            readOnlyHint=False,
            destructiveHint=False,
            idempotentHint=False,
            openWorldHint=True,
        ),
    )
    async def scale_deployment(
        name: str,
        replicas: int,
        namespace: Optional[str] = "default",
        context: str = "",
    ) -> Dict[str, Any]:
        """Scale a deployment to a specified number of replicas.

        Args:
            name: Name of the deployment
            replicas: Target number of replicas
            namespace: Namespace of the deployment (default: "default")
            context: Kubernetes context to use (uses current context if not specified)
        """
        blocked = await check_write_allowed()
        if blocked:
            return blocked
        try:
            cmd = ["kubectl", "scale", "deployment", name, f"--replicas={replicas}", "-n", namespace]
            cmd.extend(_get_kubectl_context_args(context))

            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.returncode == 0:
                return {
                    "success": True,
                    "context": context or "current",
                    "message": f"Deployment {name} scaled to {replicas} replicas"
                }
            return {"success": False, "error": result.stderr}
        except Exception as e:
            logger.error(f"Error scaling deployment: {e}")
            return {"success": False, "error": str(e)}

    @server.tool(
        annotations=ToolAnnotations(
            title="Restart Deployment",
            readOnlyHint=False,
            destructiveHint=False,
            idempotentHint=False,
            openWorldHint=True,
        ),
    )
    async def restart_deployment(
        name: str,
        namespace: str = "default",
        context: str = "",
    ) -> Dict[str, Any]:
        """Restart a deployment by triggering a rolling update.

        Args:
            name: Name of the deployment
            namespace: Namespace of the deployment (default: "default")
            context: Kubernetes context to use (uses current context if not specified)
        """
        blocked = await check_write_allowed()
        if blocked:
            return blocked
        try:
            cmd = ["kubectl", "rollout", "restart", "deployment", name, "-n", namespace]
            cmd.extend(_get_kubectl_context_args(context))

            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.returncode == 0:
                return {
                    "success": True,
                    "context": context or "current",
                    "message": f"Deployment {name} restarted"
                }
            return {"success": False, "error": result.stderr}
        except Exception as e:
            logger.error(f"Error restarting deployment: {e}")
            return {"success": False, "error": str(e)}

    @server.tool(
        annotations=ToolAnnotations(
            title="Get ReplicaSets",
            readOnlyHint=True,
            destructiveHint=False,
            idempotentHint=True,
            openWorldHint=True,
        ),
    )
    def get_replicasets(
        namespace: Optional[str] = None,
        context: str = ""
    ) -> Dict[str, Any]:
        """Get ReplicaSets in a namespace or cluster-wide.

        Args:
            namespace: Namespace to list ReplicaSets from (all namespaces if not specified)
            context: Kubernetes context to use (uses current context if not specified)
        """
        try:
            apps = get_apps_client(context)

            if namespace:
                rs_list = apps.list_namespaced_replica_set(namespace)
            else:
                rs_list = apps.list_replica_set_for_all_namespaces()

            return {
                "success": True,
                "context": context or "current",
                "replicaSets": [
                    {
