        "installed": crd_exists(CILIUM_NETWORK_POLICY_CRD, context),
        "crds": {
            "ciliumnetworkpolicies": crd_exists(CILIUM_NETWORK_POLICY_CRD, context),
            "ciliumclusterwidenetworkpolicies": crd_exists(CILIUM_CLUSTERWIDE_POLICY_CRD, context),
            "ciliumendpoints": crd_exists(CILIUM_ENDPOINT_CRD, context),
            "ciliumidentities": crd_exists(CILIUM_IDENTITY_CRD, context),
            "ciliumnodes": crd_exists(CILIUM_NODE_CRD, context),
        },
        "cli": {
            "cilium_available": _cilium_cli_available(),
            "hubble_available": _hubble_cli_available(),
        },
    }


def register_cilium_tools(mcp: FastMCP, non_destructive: bool = False):
    """Register Cilium tools with the MCP server."""

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def cilium_list_policies(
        namespace: str = "",
        context: str = "",
        include_clusterwide: bool = True
    ) -> str:
        """List Cilium network policies."""
        return json.dumps(cilium_policies_list(namespace, context, include_clusterwide), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def cilium_get_policy(
        name: str,
        namespace: str = "",
        kind: str = "CiliumNetworkPolicy",
        context: str = ""
    ) -> str:
        """Get detailed information about a Cilium network policy."""
        return json.dumps(cilium_policy_get(name, namespace, kind, context), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def cilium_list_endpoints(
        namespace: str = "",
        context: str = "",
        label_selector: str = ""
    ) -> str:
        """List Cilium endpoints with their status."""
        return json.dumps(cilium_endpoints_list(namespace, context, label_selector), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def cilium_list_identities(
        context: str = "",
        label_selector: str = ""
    ) -> str:
        """List Cilium identities."""
        return json.dumps(cilium_identities_list(context, label_selector), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def cilium_list_nodes(context: str = "") -> str:
        """List Cilium nodes with their status."""
        return json.dumps(cilium_nodes_list(context), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def cilium_get_status(context: str = "") -> str:
        """Get Cilium cluster status."""
        return json.dumps(cilium_status(context), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def get_hubble_flows(
        namespace: str = "",
        pod: str = "",
        label_selector: str = "",
        verdict: str = "",
        protocol: str = "",
        last: int = 100,
        context: str = ""
    ) -> str:
        """Query Hubble flows for network observability."""
        return json.dumps(hubble_flows_query(namespace, pod, label_selector, verdict, protocol, last, context), indent=2)

    @mcp.tool(annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=True))
    def detect_cilium(context: str = "") -> str:
        """Detect if Cilium is installed and its components."""
        return json.dumps(cilium_detect(context), indent=2)

apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "kubectl-mcp-server.fullname" . }}
  labels:
    {{- include "kubectl-mcp-server.labels" . | nindent 4 }}
spec:
  {{- if not .Values.autoscaling.enabled }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "kubectl-mcp-server.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "kubectl-mcp-server.selectorLabels" . | nindent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "kubectl-mcp-server.serviceAccountName" . }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      containers:
        - name: {{ .Chart.Name }}
          securityContext:
            {{- toYaml .Values.securityContext | nindent 12 }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          args:
            - serve
            - --transport
            - {{ .Values.mcp.transport }}
            - --port
            - "{{ .Values.mcp.port }}"
            {{- if eq .Values.safety.mode "read-only" }}
            - --read-only
            {{- else if eq .Values.safety.mode "disable-destructive" }}
            - --disable-destructive
            {{- end }}
          env:
            {{- if .Values.mcp.debug }}
            - name: MCP_DEBUG
              value: "true"
            {{- end }}
            {{- if .Values.mcp.logFile }}
            - name: MCP_LOG_FILE
              value: {{ .Values.mcp.logFile | quote }}
            {{- end }}
            {{- if .Values.browser.enabled }}
            - name: MCP_BROWSER_ENABLED
              value: "true"
            - name: MCP_BROWSER_PROVIDER
              value: {{ .Values.browser.provider | quote }}
            {{- if and (eq .Values.browser.provider "browserbase") .Values.browser.browserbase.apiKey }}
            - name: BROWSERBASE_API_KEY
              valueFrom:
                secretKeyRef:
                  name: {{ include "kubectl-mcp-server.fullname" . }}-browser
                  key: browserbase-api-key
            - name: BROWSERBASE_PROJECT_ID
              value: {{ .Values.browser.browserbase.projectId | quote }}
            {{- end }}
            {{- if and (eq .Values.browser.provider "browseruse") .Values.browser.browseruse.apiKey }}
            - name: BROWSER_USE_API_KEY
              valueFrom:
                secretKeyRef:
                  name: {{ include "kubectl-mcp-server.fullname" . }}-browser
                  key: browseruse-api-key
            {{- end }}
            {{- end }}
            {{- with .Values.extraEnv }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
          ports:
            - name: http
              containerPort: {{ .Values.mcp.port }}
              protocol: TCP
          {{- if .Values.livenessProbe.enabled }}
          livenessProbe:
            httpGet:
              path: /health
              port: http
            initialDelaySeconds: {{ .Values.livenessProbe.initialDelaySeconds }}
            periodSeconds: {{ .Values.livenessProbe.periodSeconds }}
            timeoutSeconds: {{ .Values.livenessProbe.timeoutSeconds }}
            failureThreshold: {{ .Values.livenessProbe.failureThreshold }}
          {{- end }}
          {{- if .Values.readinessProbe.enabled }}
          readinessProbe:
            httpGet:
              path: /health
              port: http
            initialDelaySeconds: {{ .Values.readinessProbe.initialDelaySeconds }}
            periodSeconds: {{ .Values.readinessProbe.periodSeconds }}
            timeoutSeconds: {{ .Values.readinessProbe.timeoutSeconds }}
            failureThreshold: {{ .Values.readinessProbe.failureThreshold }}
          {{- end }}
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          {{- with .Values.extraVolumeMounts }}
          volumeMounts:
            {{- toYaml . | nindent 12 }}
          {{- end }}
      {{- with .Values.extraVolumes }}
      volumes:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

import React, { useState, useEffect, useCallback } from "react";
import { Table, StatusBadge, ProgressBar } from "@shared/components";
import type { Column } from "@shared/components";
import { baseStyles, getTheme, setTheme, type Theme } from "@shared/theme";

interface Deployment {
  name: string;
  namespace: string;
  replicas: number;
  readyReplicas: number;
  updatedReplicas: number;
  availableReplicas: number;
  strategy: string;
  age: string;
  image: string;
  conditions?: Array<{ type: string; status: string; reason?: string }>;
}

interface AppState {
  deployments: Deployment[];
  namespaces: string[];
  loading: boolean;
  error: string | null;
  selectedNamespace: string;
  searchQuery: string;
  selectedDeployment: Deployment | null;
  scaleModalOpen: boolean;
  scaleReplicas: number;
  theme: Theme;
}

declare global {
  interface Window {
    callServerTool?: (request: {
      name: string;
      arguments?: Record<string, unknown>;
    }) => Promise<{ content: Array<{ type: string; text: string }> }>;
    initialArgs?: {
      namespace?: string;
      context?: string;
    };
  }
}

export function DeploymentDashboard(): React.ReactElement {
  const [state, setState] = useState<AppState>({
    deployments: [],
    namespaces: ["all"],
    loading: true,
    error: null,
    selectedNamespace: window.initialArgs?.namespace || "all",
    searchQuery: "",
    selectedDeployment: null,
    scaleModalOpen: false,
    scaleReplicas: 1,
    theme: getTheme(),
  });

  const callTool = useCallback(
    async (name: string, args: Record<string, unknown> = {}) => {
      if (!window.callServerTool) {
        console.warn("callServerTool not available");
        return null;
      }
      try {
        const result = await window.callServerTool({ name, arguments: args });
        const text = result.content[0]?.text;
        return text ? JSON.parse(text) : null;
      } catch (error) {
        console.error(`Tool call failed: ${name}`, error);
        throw error;
      }
    },
    []
  );

  const fetchDeployments = useCallback(async () => {
    setState((prev) => ({ ...prev, loading: true, error: null }));
    try {
      const namespace =
        state.selectedNamespace === "all" ? "" : state.selectedNamespace;
      const data = await callTool("get_deployments", {
        namespace,
        context: window.initialArgs?.context || "",
      });

      if (data?.deployments) {
        setState((prev) => ({
          ...prev,
          deployments: data.deployments,
          loading: false,
        }));
      } else {
        setState((prev) => ({
          ...prev,
          deployments: getMockDeployments(),
          loading: false,
        }));
      }
    } catch (error) {
      setState((prev) => ({
        ...prev,
        deployments: getMockDeployments(),
        loading: false,
        error:
          error instanceof Error ? error.message : "Failed to fetch deployments",
      }));
    }
  }, [callTool, state.selectedNamespace]);

  const fetchNamespaces = useCallback(async () => {
    try {
      const data = await callTool("get_namespaces", {
        context: window.initialArgs?.context || "",
      });
      if (data?.namespaces) {
        const names = data.namespaces.map((ns: { name: string }) => ns.name);
        setState((prev) => ({
          ...prev,
          namespaces: ["all", ...names],
        }));
      }
    } catch {
      setState((prev) => ({
        ...prev,
        namespaces: ["all", "default", "kube-system"],
      }));
    }
  }, [callTool]);

  useEffect(() => {
    fetchNamespaces();
    fetchDeployments();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetch on mount only
  }, []);

  useEffect(() => {
    fetchDeployments();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- re-fetch when namespace changes
  }, [state.selectedNamespace]);

  const handleScale = useCallback(
    async (deployment: Deployment, replicas: number) => {
      try {
        await callTool("scale_deployment", {
          name: deployment.name,
          namespace: deployment.namespace,
          replicas,
          context: window.initialArgs?.context || "",
        });
        fetchDeployments();
        setState((prev) => ({ ...prev, scaleModalOpen: false }));
      } catch (error) {
        alert(
          `Failed to scale: ${error instanceof Error ? error.message : error}`
        );
      }
    },
    [callTool, fetchDeployments]
  );

  const handleRestart = useCallback(
    async (deployment: Deployment) => {
      if (!confirm(`Restart deployment ${deployment.name}?`)) return;
      try {
        await callTool("restart_deployment", {
          name: deployment.name,
          namespace: deployment.namespace,
          context: window.initialArgs?.context || "",
        });
        fetchDeployments();
      } catch (error) {
        alert(
          `Failed to restart: ${error instanceof Error ? error.message : error}`
        );
      }
    },
    [callTool, fetchDeployments]
  );

  const handleRollback = useCallback(
    async (deployment: Deployment) => {
      if (!confirm(`Rollback deployment ${deployment.name} to previous revision?`))
        return;
      try {
        await callTool("rollback_deployment", {
          name: deployment.name,
          namespace: deployment.namespace,
          revision: 0,
          context: window.initialArgs?.context || "",
        });
        fetchDeployments();
      } catch (error) {
        alert(
          `Failed to rollback: ${error instanceof Error ? error.message : error}`
        );
      }
    },
    [callTool, fetchDeployments]
  );

  const openScaleModal = useCallback((deployment: Deployment) => {
    setState((prev) => ({
      ...prev,
      selectedDeployment: deployment,
      scaleReplicas: deployment.replicas,
      scaleModalOpen: true,
    }));
  }, []);

  const toggleTheme = useCallback(() => {
    const newTheme = state.theme === "dark" ? "light" : "dark";
    setTheme(newTheme);
    setState((prev) => ({ ...prev, theme: newTheme }));
  }, [state.theme]);

  const filteredDeployments = state.deployments.filter((d) => {
    if (!state.searchQuery) return true;
    const query = state.searchQuery.toLowerCase();
    return (
      d.name.toLowerCase().includes(query) ||
      d.namespace.toLowerCase().includes(query) ||
      d.image.toLowerCase().includes(query)
    );
  });

  const getDeploymentStatus = (d: Deployment): string => {
    if (d.replicas === 0) return "Scaled to zero";
    if (d.readyReplicas === d.replicas && d.replicas > 0) return "Running";
    if (d.updatedReplicas < d.replicas) return "Progressing";
    if (d.readyReplicas === 0) return "Failed";
    return "Degraded";
  };

  const columns: Column<Deployment>[] = [
    {
      key: "name",
      header: "Name",
      width: "25%",
      render: (d) => (
        <div className="deployment-name">
          <span className="name">{d.name}</span>
          <span className="namespace">{d.namespace}</span>
        </div>
      ),
    },
    {
      key: "status",
      header: "Status",
      width: "12%",
      render: (d) => <StatusBadge status={getDeploymentStatus(d)} />,
    },
    {
      key: "replicas",
      header: "Replicas",
      width: "15%",
      render: (d) => (
        <div className="replicas">
          <ProgressBar
            value={d.readyReplicas}
            max={d.replicas || 1}
            size="sm"
            showPercentage={false}
            color={d.readyReplicas === d.replicas ? "success" : "warning"}
          />
          <span className="replica-count">
            {d.readyReplicas}/{d.replicas}
          </span>
        </div>
      ),
    },
    {
      key: "strategy",
      header: "Strategy",
      width: "10%",
    },
    {
      key: "image",
      header: "Image",
      width: "20%",
      render: (d) => (
        <span className="image" title={d.image}>
          {d.image.split("/").pop()?.split(":")[0] || d.image}
        </span>
      ),
    },
    {
      key: "age",
      header: "Age",
      width: "8%",
    },
    {
      key: "actions",
      header: "Actions",
      width: "10%",
      sortable: false,
      render: (d) => (
        <div className="actions">
          <button
            className="btn-icon"
            onClick={() => openScaleModal(d)}
            title="Scale"
          >
            ⚖️
          </button>
          <button
            className="btn-icon"
            onClick={() => handleRestart(d)}
            title="Restart"
          >
            🔄
          </button>
          <button
            className="btn-icon"
            onClick={() => handleRollback(d)}
            title="Rollback"
          >
            ⏪
          </button>
        </div>
      ),
    },
  ];

  return (
    <div className="app" data-theme={state.theme}>
      <style>{baseStyles}</style>
      <style>{appStyles}</style>

      <header className="app-header">
        <div className="header-left">
          <h1>Deployments</h1>
          <span className="count">{filteredDeployments.length} deployments</span>
        </div>
        <div className="header-right">
          <input
            type="text"
            placeholder="Search deployments..."
            value={state.searchQuery}
            onChange={(e) =>
              setState((prev) => ({ ...prev, searchQuery: e.target.value }))
            }
            className="search-input"
          />
          <select
            value={state.selectedNamespace}
            onChange={(e) =>
              setState((prev) => ({
                ...prev,
                selectedNamespace: e.target.value,
              }))
            }
            className="namespace-select"
          >
            {state.namespaces.map((ns) => (
              <option key={ns} value={ns}>
                {ns === "all" ? "All Namespaces" : ns}
              </option>
            ))}
          </select>
          <button
            onClick={fetchDeployments}
            className="btn-refresh"
            title="Refresh"
          >
            🔄
          </button>
          <button onClick={toggleTheme} className="btn-theme" title="Toggle Theme">
            {state.theme === "dark" ? "☀️" : "🌙"}
          </button>
        </div>
      </header>

      {state.error && (
        <div className="error-banner">
          {state.error}
          <button onClick={() => setState((prev) => ({ ...prev, error: null }))}>
            ✕
          </button>
        </div>
      )}

      <main className="app-main">
        <Table
          data={filteredDeployments}
          columns={columns}
          keyExtractor={(d) => `${d.namespace}/${d.name}`}
          loading={state.loading}
          emptyMessage="No deployments found"
        />
      </main>

      {state.scaleModalOpen && state.selectedDeployment && (
        <div className="modal-overlay" onClick={() => setState((prev) => ({ ...prev, scaleModalOpen: false }))}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h2>Scale Deployment</h2>
            <p>
              Scaling <strong>{state.selectedDeployment.name}</strong> in{" "}
              {state.selectedDeployment.namespace}
            </p>
            <div className="scale-input">
              <label>Replicas:</label>
              <input
                type="number"
                min="0"
                max="100"
                value={state.scaleReplicas}
                onChange={(e) =>
                  setState((prev) => ({
                    ...prev,
                    scaleReplicas: Number(e.target.value),
                  }))
                }
              />
            </div>
            <div className="modal-actions">
              <button
                className="btn-secondary"
                onClick={() =>
                  setState((prev) => ({ ...prev, scaleModalOpen: false }))
                }
              >
                Cancel
              </button>
              <button
                className="btn-primary"
                onClick={() =>
                  handleScale(state.selectedDeployment!, state.scaleReplicas)
                }
              >
                Scale
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

